package android.view;
import android.graphics.Insets;
import android.graphics.Rect;
public class WindowInsets {
    public static final WindowInsets CONSUMED=new WindowInsets();
    private final Insets[] values=new Insets[9]; private int visible=0x1ff; private DisplayCutout cutout;
    public WindowInsets(Rect insets){values[0]=Insets.of(insets);}
    public WindowInsets(WindowInsets source){for(int i=0;i<values.length;i++)values[i]=source.values[i];visible=source.visible;cutout=source.cutout;}
    private WindowInsets(){}
    public int getSystemWindowInsetLeft(){return getInsets(Type.systemBars()).left;} public int getSystemWindowInsetTop(){return getInsets(Type.systemBars()).top;} public int getSystemWindowInsetRight(){return getInsets(Type.systemBars()).right;} public int getSystemWindowInsetBottom(){return getInsets(Type.systemBars()).bottom;}
    public boolean hasSystemWindowInsets(){return !getInsets(Type.systemBars()).equals(Insets.NONE);} public boolean hasInsets(){return !getInsets(0x1ff).equals(Insets.NONE);} public boolean isConsumed(){return !hasInsets();} public boolean isRound(){return false;}
    public Insets getInsets(int mask){int l=0,t=0,r=0,b=0;for(int i=0;i<values.length;i++)if((mask&(1<<i))!=0&&values[i]!=null){Insets v=values[i];l=Math.max(l,v.left);t=Math.max(t,v.top);r=Math.max(r,v.right);b=Math.max(b,v.bottom);}return Insets.of(l,t,r,b);}
    public Insets getInsetsIgnoringVisibility(int mask){return getInsets(mask);} public boolean isVisible(int mask){return (visible&mask)==mask;} public DisplayCutout getDisplayCutout(){return cutout;}
    public Insets getSystemWindowInsets(){return getInsets(Type.systemBars());} public Insets getSystemGestureInsets(){return getInsets(Type.systemGestures());} public Insets getMandatorySystemGestureInsets(){return getInsets(Type.mandatorySystemGestures());} public Insets getTappableElementInsets(){return getInsets(Type.tappableElement());}
    public int getStableInsetLeft(){return getSystemWindowInsetLeft();} public int getStableInsetTop(){return getSystemWindowInsetTop();} public int getStableInsetRight(){return getSystemWindowInsetRight();} public int getStableInsetBottom(){return getSystemWindowInsetBottom();}
    public WindowInsets consumeStableInsets(){return consumeSystemWindowInsets();} public WindowInsets consumeDisplayCutout(){WindowInsets out=new WindowInsets(this);out.cutout=null;return out;} public RoundedCorner getRoundedCorner(int position){return null;}
    public WindowInsets inset(int l,int t,int r,int b){WindowInsets out=new WindowInsets(this);for(int i=0;i<values.length;i++){Insets v=values[i];if(v!=null)out.values[i]=Insets.of(Math.max(0,v.left-l),Math.max(0,v.top-t),Math.max(0,v.right-r),Math.max(0,v.bottom-b));}return out;}
    public WindowInsets consumeSystemWindowInsets(){WindowInsets out=new WindowInsets(this);out.values[0]=out.values[1]=null;return out;}
    public WindowInsets replaceSystemWindowInsets(int l,int t,int r,int b){WindowInsets out=new WindowInsets(this);out.values[0]=Insets.of(l,t,r,b);return out;}
    public static final class Type { public static int statusBars(){return 1;} public static int navigationBars(){return 2;} public static int captionBar(){return 4;} public static int ime(){return 8;} public static int systemGestures(){return 16;} public static int mandatorySystemGestures(){return 32;} public static int tappableElement(){return 64;} public static int displayCutout(){return 128;} public static int systemBars(){return 1|2|4;} }
    public static final class Side { public static final int LEFT=1,TOP=2,RIGHT=4,BOTTOM=8,ALL=15; }
    public static final class Builder { private final WindowInsets value; public Builder(){value=new WindowInsets();} public Builder(WindowInsets source){value=new WindowInsets(source);} public Builder setInsets(int mask,Insets insets){for(int i=0;i<value.values.length;i++)if((mask&(1<<i))!=0)value.values[i]=insets;return this;} public Builder setInsetsIgnoringVisibility(int mask,Insets insets){return setInsets(mask,insets);} public Builder setVisible(int mask,boolean visible){if(visible)value.visible|=mask;else value.visible&=~mask;return this;} public Builder setStableInsets(Insets insets){return setInsets(Type.systemBars(),insets);} public Builder setSystemGestureInsets(Insets insets){return setInsets(Type.systemGestures(),insets);} public Builder setMandatorySystemGestureInsets(Insets insets){return setInsets(Type.mandatorySystemGestures(),insets);} public Builder setTappableElementInsets(Insets insets){return setInsets(Type.tappableElement(),insets);} public Builder setSystemWindowInsets(Insets insets){return setInsets(Type.systemBars(),insets);} public Builder setDisplayCutout(DisplayCutout c){value.cutout=c;return this;} public WindowInsets build(){return new WindowInsets(value);} }
}
